const specs = [["Speed_0","uint16",1]];
const width = { uint16: 1, int16: 1, int32: 2, float32: 2, float64: 4 };
const values = {};
let at = 0;
for (const [name, type, scale] of specs) {
  let words = msg.payload.slice(at, at + width[type]);
  at += width[type];
  words = words.map((w) => ((w & 0xff) << 8) | (w >> 8));
  const view = new DataView(new ArrayBuffer(8));
  words.forEach((w, i) => view.setUint16(i * 2, w));
  const raw = type === 'uint16' ? view.getUint16(0) : type === 'int16' ? view.getInt16(0) : type === 'int32' ? view.getInt32(0)
    : type === 'float32' ? view.getFloat32(0) : view.getFloat64(0);
  values[name] = raw * scale;
}
msg.payload = values;
msg.topic = "Pump RTU";
return msg;

